WildlifeKnockout = WildlifeKnockout or {} WildlifeKnockout._type = WildlifeKnockout function WildlifeKnockout:Down(wake) self.player = GetLocalPlayerId() if wake then SetScriptedDeath(1) self.died = CScriptCallbackSystem_GetInstance():RegisterEventCallback(self.player, self, "Event_Died", "PlayerDied") else BlockBuddyRescue() self:After(1, "Unblock") end SendPierceStimNoOrigin(self.player, 32) SendPierceStimNoOrigin(self.player, 32) end function WildlifeKnockout:After(seconds, method) local delays = CDominoDelayManager_GetInstance() delays:SendCommand(delays:CreateDelay(seconds, self, method), "start") end function WildlifeKnockout:Unblock() UnblockBuddyRescue() end function WildlifeKnockout:Event_Died() CScriptCallbackSystem_GetInstance():RemoveCallback(self.player, self.died) self:After(2, "WakeUp") end function WildlifeKnockout:WakeUp() local domino = CDominoManager_GetInstance() domino:SendCommandEventToEntity(self.player, "SetupPlayerForAnchorAnim", 1) domino:SendCommandEventToEntity2(self.player, "PlayAnim", self, "AnimCommandSent", "pawn_generic_desertgetup", 0, 1) domino:SendRegisteredEventToEntity(self.player, "CFCXCountersComponentPlayerSP_HealingDone") SetScriptedDeath(0) end function WildlifeKnockout:AnimCommandSent() end
